add_action( 'wp_loaded', 'perfectpixel_coupon_from_url_capture', 30 );
add_action( 'woocommerce_add_to_cart', 'perfectpixel_coupon_from_url_apply', 30 );

function perfectpixel_coupon_from_url_capture() {
	$param = sanitize_key( '{{coupon_url_param}}' );
	if ( is_admin() || wp_doing_ajax() || ! function_exists( 'WC' ) || ! WC()->session || empty( $_GET[ $param ] ) ) {
		return;
	}
	$code = wc_format_coupon_code( wp_unslash( $_GET[ $param ] ) );
	if ( $code && wc_get_coupon_id_by_code( $code ) ) {
		if ( ! WC()->session->has_session() ) {
			WC()->session->set_customer_session_cookie( true );
		}
		WC()->session->set( 'perfectpixel_url_coupon', $code );
		perfectpixel_coupon_from_url_apply();
	}
}

function perfectpixel_coupon_from_url_apply() {
	if ( ! WC()->session || ! WC()->cart || WC()->cart->is_empty() ) {
		return;
	}
	$code = WC()->session->get( 'perfectpixel_url_coupon' );
	if ( $code && ! WC()->cart->has_discount( $code ) ) {
		WC()->cart->apply_coupon( $code );
		WC()->session->set( 'perfectpixel_url_coupon', null );
	}
}
